arguments.cmd:
mkdir -p /app/output && cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>CreativeHub — Online Classes for Creatives</title>
  <meta name="description" content="CreativeHub is an online learning community with thousands of creative classes from illustration and design to photography and filmmaking." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #f8fafc;
      --surface: #ffffff;
      --surface-soft: #f1f5f9;
      --text: #0f172a;
      --muted: #475569;
      --hero-bg: #0b1020;
      --accent-coral: #ff6b4a;
      --accent-green: #7eff8a;
      --accent-yellow: #ffd85e;
      --accent-blue: #7aa2ff;
      --border: #dbe5ef;
      --shadow: 0 12px 35px rgba(15, 23, 42, 0.08);
      --radius-xl: 24px;
      --radius-lg: 18px;
      --radius-md: 12px;
      --max: 1160px;
    }

    * { box-sizing: border-box; }

    html, body {
      margin: 0;
      padding: 0;
      background: var(--bg);
      color: var(--text);
      font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      line-height: 1.5;
      scroll-behavior: smooth;
    }

    img { max-width: 100%; display: block; }
    a { color: inherit; text-decoration: none; }

    .container {
      width: min(var(--max), 92vw);
      margin: 0 auto;
    }

    .section { padding: 72px 0; }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 0.78rem;
      letter-spacing: .08em;
      text-transform: uppercase;
      font-weight: 700;
      color: #1e293b;
      background: #e2e8f0;
      border-radius: 999px;
      padding: 8px 12px;
    }

    .heading {
      margin: 14px 0 12px;
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      font-size: clamp(1.9rem, 3.8vw, 3.25rem);
      line-height: 1.08;
      letter-spacing: -0.02em;
    }

    .sub {
      color: var(--muted);
      margin: 0;
      font-size: clamp(1rem, 1.9vw, 1.13rem);
      max-width: 70ch;
    }

    header.nav-wrap {
      position: sticky;
      top: 0;
      z-index: 50;
      backdrop-filter: blur(10px);
      background: rgba(248,250,252,.86);
      border-bottom: 1px solid rgba(148,163,184,.22);
    }

    .nav {
      height: 72px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 10px;
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      font-size: 1.1rem;
      font-weight: 800;
    }

    .brand-badge {
      width: 34px;
      height: 34px;
      border-radius: 10px;
      background: linear-gradient(135deg, var(--accent-coral), #ff9b5a);
      display: grid;
      place-items: center;
      color: #fff;
      box-shadow: 0 8px 20px rgba(255,107,74,.36);
      font-weight: 800;
      font-size: .96rem;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 20px;
      color: #334155;
      font-weight: 600;
      font-size: .95rem;
    }

    .btn {
      border: 0;
      border-radius: 12px;
      padding: 12px 16px;
      font-weight: 700;
      font-family: inherit;
      cursor: pointer;
      transition: transform .15s ease, box-shadow .2s ease, background .2s ease;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 10px;
    }

    .btn:hover { transform: translateY(-1px); }
    .btn:active { transform: translateY(0); }

    .btn-primary {
      background: linear-gradient(135deg, var(--accent-coral), #ff8a3d);
      color: #fff;
      box-shadow: 0 12px 30px rgba(255,107,74,.35);
    }

    .btn-dark {
      background: #0f172a;
      color: #fff;
      box-shadow: 0 10px 24px rgba(15,23,42,.26);
    }

    .btn-soft {
      background: #e2e8f0;
      color: #0f172a;
    }

    .hero {
      background:
        radial-gradient(circle at 82% 16%, rgba(126,255,138,.17), transparent 36%),
        radial-gradient(circle at 70% 74%, rgba(122,162,255,.2), transparent 44%),
        radial-gradient(circle at 18% 88%, rgba(255,107,74,.2), transparent 38%),
        var(--hero-bg);
      color: #e2e8f0;
      padding: 68px 0 60px;
      border-radius: 0 0 34px 34px;
      overflow: clip;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1.08fr .92fr;
      align-items: center;
      gap: 34px;
    }

    .hero h1 {
      margin: 0;
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      font-size: clamp(2.1rem, 6vw, 4.2rem);
      line-height: 1.02;
      letter-spacing: -.03em;
      color: #fff;
      max-width: 14ch;
    }

    .hero p {
      margin: 18px 0 26px;
      color: #cbd5e1;
      max-width: 54ch;
      font-size: 1.05rem;
    }

    .signup-panel {
      background: rgba(15, 23, 42, .65);
      border: 1px solid rgba(148,163,184,.3);
      border-radius: var(--radius-xl);
      padding: 18px;
      box-shadow: 0 24px 44px rgba(2,6,23,.36);
      max-width: 500px;
    }

    .signup-row {
      display: grid;
      grid-template-columns: 1fr;
      gap: 12px;
    }

    .btn-hero {
      width: 100%;
      justify-content: flex-start;
      padding: 14px 16px;
      border-radius: 14px;
      font-size: .97rem;
    }

    .btn-google {
      background: #fff;
      color: #0f172a;
    }

    .btn-email {
      background: #1e293b;
      color: #fff;
      border: 1px solid rgba(148,163,184,.3);
    }

    .hero-note {
      margin: 12px 0 0;
      color: #94a3b8;
      font-size: .82rem;
    }

    .pill-row {
      margin-top: 20px;
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
    }

    .pill {
      background: rgba(148,163,184,.18);
      border: 1px solid rgba(148,163,184,.35);
      color: #e2e8f0;
      border-radius: 999px;
      padding: 8px 12px;
      font-size: .84rem;
      font-weight: 600;
    }

    .hero-card {
      background: linear-gradient(180deg, #fff, #f8fafc);
      color: #0f172a;
      border-radius: var(--radius-xl);
      padding: 24px;
      box-shadow: var(--shadow);
      transform: rotate(-1deg);
    }

    .hero-card .spot {
      height: 190px;
      border-radius: 16px;
      background:
      radial-gradient(circle at 20% 30%, rgba(255,107,74,.36), transparent 50%),
      radial-gradient(circle at 72% 24%, rgba(126,255,138,.35), transparent 45%),
      radial-gradient(circle at 40% 78%, rgba(122,162,255,.35), transparent 48%),
      linear-gradient(120deg, #0f172a, #1e293b);
      position: relative;
      overflow: hidden;
    }

    .hero-card .spot::after {
      content: "LIVE WORKSHOP";
      position: absolute;
      top: 12px;
      left: 12px;
      font-size: .73rem;
      font-weight: 800;
      color: #0f172a;
      background: var(--accent-yellow);
      border-radius: 999px;
      padding: 6px 10px;
    }

    .meta {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 10px;
      margin-top: 14px;
    }

    .meta div {
      background: #f1f5f9;
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 11px;
      font-size: .84rem;
      color: #475569;
    }

    .features-grid, .test-grid, .teams-grid {
      display: grid;
      gap: 16px;
      margin-top: 26px;
      grid-template-columns: repeat(3, minmax(0,1fr));
    }

    .card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 18px;
      box-shadow: var(--shadow);
    }

    .card h3 {
      margin: 12px 0 8px;
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      font-size: 1.1rem;
    }

    .card p { margin: 0; color: var(--muted); }

    .icon-dot {
      width: 42px;
      height: 42px;
      border-radius: 12px;
      display: grid;
      place-items: center;
      font-weight: 800;
      font-size: 1.2rem;
      color: #fff;
    }

    .stats-band {
      margin: 16px 0;
      background: linear-gradient(135deg, #111827, #0f172a);
      color: #fff;
      border-radius: 24px;
      padding: 32px 24px;
    }

    .stats-grid {
      display: grid;
      gap: 16px;
      grid-template-columns: repeat(4, minmax(0,1fr));
      text-align: center;
    }

    .stat-num {
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      font-size: clamp(2rem, 4.2vw, 3.15rem);
      line-height: 1;
      letter-spacing: -.03em;
      margin: 0;
    }

    .stat-label {
      margin-top: 8px;
      color: #cbd5e1;
      font-size: .95rem;
      font-weight: 500;
    }

    .tabs {
      margin-top: 26px;
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
    }

    .tab-btn {
      border: 1px solid var(--border);
      background: #fff;
      border-radius: 999px;
      padding: 9px 14px;
      font-weight: 700;
      cursor: pointer;
      transition: .2s ease;
      color: #334155;
    }

    .tab-btn[aria-selected="true"] {
      background: #0f172a;
      color: #fff;
      border-color: #0f172a;
      box-shadow: 0 10px 20px rgba(15,23,42,.18);
    }

    .course-grid {
      margin-top: 20px;
      display: grid;
      gap: 16px;
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .course-card {
      background: #fff;
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow);
      transition: transform .15s ease, box-shadow .2s ease;
    }

    .course-card:hover {
      transform: translateY(-3px);
      box-shadow: 0 18px 35px rgba(15,23,42,.12);
    }

    .thumb {
      height: 160px;
      position: relative;
      overflow: hidden;
    }

    .thumb::after {
      content: attr(data-category);
      position: absolute;
      left: 12px;
      top: 12px;
      background: rgba(255,255,255,.9);
      color: #0f172a;
      padding: 6px 10px;
      border-radius: 999px;
      font-size: .72rem;
      font-weight: 700;
    }

    .course-body { padding: 14px; }

    .course-title {
      margin: 0;
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      font-size: 1rem;
      line-height: 1.25;
    }

    .course-teacher {
      margin: 6px 0 10px;
      color: #64748b;
      font-weight: 600;
      font-size: .9rem;
    }

    .course-meta {
      display: flex;
      justify-content: space-between;
      font-size: .84rem;
      color: #475569;
      border-top: 1px solid #e2e8f0;
      padding-top: 9px;
    }

    .feed-grid {
      margin-top: 24px;
      display: grid;
      gap: 12px;
      grid-template-columns: repeat(4, minmax(0,1fr));
    }

    .feed-item {
      aspect-ratio: 1/1;
      border-radius: 16px;
      border: 1px solid var(--border);
      overflow: hidden;
      box-shadow: var(--shadow);
      position: relative;
      background: #cbd5e1;
    }

    .feed-item span {
      position: absolute;
      left: 10px;
      bottom: 10px;
      font-size: .77rem;
      font-weight: 700;
      color: #fff;
      background: rgba(15,23,42,.7);
      padding: 6px 8px;
      border-radius: 999px;
    }

    .teacher-head {
      margin-top: 22px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 10px;
    }

    .carousel-wrap {
      overflow: hidden;
      margin-top: 14px;
    }

    .carousel-track {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: minmax(240px, 1fr);
      gap: 14px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      scrollbar-width: thin;
      padding-bottom: 6px;
    }

    .teacher-card {
      scroll-snap-align: start;
      background: #fff;
      border: 1px solid var(--border);
      border-radius: 16px;
      overflow: hidden;
      box-shadow: var(--shadow);
      min-width: 240px;
    }

    .teacher-img {
      height: 165px;
      background: linear-gradient(135deg, #1e293b, #334155);
    }

    .teacher-body { padding: 12px; }
    .teacher-name { margin: 0; font-family: "Plus Jakarta Sans"; font-size: 1rem; }
    .teacher-role { margin: 4px 0 0; font-size: .9rem; color: #475569; }

    .arrow-btn {
      width: 38px;
      height: 38px;
      border-radius: 999px;
      border: 1px solid var(--border);
      background: #fff;
      cursor: pointer;
      font-weight: 900;
      color: #0f172a;
    }

    .faq {
      margin-top: 24px;
      display: grid;
      gap: 10px;
    }

    .faq-item {
      border: 1px solid var(--border);
      background: #fff;
      border-radius: 14px;
      overflow: hidden;
      box-shadow: var(--shadow);
    }

    .faq-btn {
      width: 100%;
      text-align: left;
      padding: 15px 16px;
      border: 0;
      font-size: 1rem;
      font-weight: 700;
      background: transparent;
      display: flex;
      justify-content: space-between;
      align-items: center;
      cursor: pointer;
    }

    .faq-btn span:last-child { color: #64748b; font-size: 1.15rem; }

    .faq-panel {
      max-height: 0;
      overflow: hidden;
      transition: max-height .26s ease;
      border-top: 1px solid transparent;
    }

    .faq-panel p {
      margin: 0;
      padding: 0 16px 14px;
      color: #475569;
    }

    .faq-item[data-open="true"] .faq-panel {
      max-height: 220px;
      border-top-color: #e2e8f0;
    }

    .test-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
    .quote { font-size: 1rem; color: #1e293b; margin: 0 0 12px; }
    .who { color: #64748b; font-weight: 600; margin: 0; }

    .teams-grid {
      grid-template-columns: repeat(5, minmax(0,1fr));
      margin-top: 20px;
    }

    .team-logo {
      background: #fff;
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 20px 10px;
      text-align: center;
      font-family: "Plus Jakarta Sans";
      font-weight: 800;
      color: #334155;
      box-shadow: var(--shadow);
    }

    footer {
      background: #0f172a;
      color: #cbd5e1;
      margin-top: 60px;
      padding: 38px 0;
    }

    .footer-grid {
      display: grid;
      gap: 20px;
      grid-template-columns: 1.1fr .9fr;
      align-items: start;
    }

    .small { font-size: .85rem; color: #94a3b8; }

    .modal-backdrop {
      position: fixed;
      inset: 0;
      background: rgba(2,6,23,.65);
      display: none;
      place-items: center;
      z-index: 80;
      padding: 18px;
    }

    .modal-backdrop[data-open="true"] { display: grid; }

    .modal {
      background: #fff;
      width: min(480px, 95vw);
      border-radius: 18px;
      border: 1px solid var(--border);
      box-shadow: 0 25px 50px rgba(2,6,23,.36);
      padding: 20px;
    }

    .modal h3 {
      margin: 0 0 10px;
      font-family: "Plus Jakarta Sans";
      font-size: 1.3rem;
    }

    .input {
      width: 100%;
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 11px 12px;
      font: inherit;
      margin: 8px 0 14px;
    }

    @media (max-width: 1050px) {
      .hero-grid { grid-template-columns: 1fr; }
      .course-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .feed-grid { grid-template-columns: repeat(3, minmax(0,1fr)); }
      .stats-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .teams-grid { grid-template-columns: repeat(3, minmax(0,1fr)); }
    }

    @media (max-width: 760px) {
      .nav-links a:nth-child(-n+2) { display: none; }
      .features-grid, .course-grid, .feed-grid, .test-grid { grid-template-columns: 1fr; }
      .teams-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .footer-grid { grid-template-columns: 1fr; }
      .section { padding: 56px 0; }
    }
  </style>
</head>
<body>
  <header class="nav-wrap">
    <div class="container nav">
      <a class="brand" href="#">
        <span class="brand-badge">CH</span>
        <span>CreativeHub</span>
      </a>
      <nav class="nav-links" aria-label="Main navigation">
        <a href="#">Browse</a>
        <a href="#">Sign In</a>
        <button class="btn btn-primary" type="button">Sign Up</button>
      </nav>
    </div>
  </header>

  <section class="hero">
    <div class="container hero-grid">
      <div>
        <span class="eyebrow" style="background:rgba(255,255,255,.14); color:#f8fafc;">Create • Learn • Grow</span>
        <h1>Learn Creative Skills from Industry Pros</h1>
        <p>Join a global community of makers. Explore thousands of classes in illustration, design, animation, photography, and more — then build real projects with expert feedback.</p>

        <div class="signup-panel" aria-label="Hero sign up options">
          <div class="signup-row">
            <button class="btn btn-hero btn-google" id="googleSignupBtn" type="button" aria-label="Continue with Google">⚪ Continue with Google</button>
            <button class="btn btn-hero btn-email" id="emailSignupBtn" type="button" aria-label="Continue with email">✉ Continue with email</button>
          </div>
          <p class="hero-note">Try CreativeHub free for 7 days. Cancel anytime.</p>
        </div>

        <div class="pill-row" aria-label="Course categories">
          <span class="pill">Graphic Design</span>
          <span class="pill">Illustration</span>
          <span class="pill">Animation</span>
          <span class="pill">Film &amp; Video</span>
          <span class="pill">Freelance</span>
          <span class="pill">UI/UX Design</span>
        </div>
      </div>

      <aside class="hero-card" aria-label="Featured workshop highlight">
        <div class="spot"></div>
        <div class="meta">
          <div><strong>New This Week</strong><br>Visual Storytelling for Creators</div>
          <div><strong>42k+ students</strong><br>Across design tracks</div>
          <div><strong>Project-based</strong><br>Build your portfolio</div>
          <div><strong>4.8 rating</strong><br>App Store average</div>
        </div>
      </aside>
    </div>
  </section>

  <main>
    <section class="section">
      <div class="container">
        <span class="eyebrow">Why CreativeHub</span>
        <h2 class="heading">Built for creative momentum</h2>
        <p class="sub">Learn on your schedule, follow structured paths, and get inspired by a thriving community of artists, designers, filmmakers, and creative entrepreneurs.</p>

        <div class="features-grid">
          <article class="card">
            <div class="icon-dot" style="background:#ff6b4a;">✦</div>
            <h3>Hands-on Projects</h3>
            <p>Practice while you learn with bite-sized assignments that turn into real portfolio pieces.</p>
          </article>
          <article class="card">
            <div class="icon-dot" style="background:#7aa2ff;">▶</div>
            <h3>Stream Anywhere</h3>
            <p>Watch lessons across desktop and mobile with downloadable resources and class notes.</p>
          </article>
          <article class="card">
            <div class="icon-dot" style="background:#10b981;">✓</div>
            <h3>Expert Feedback</h3>
            <p>Receive guidance from seasoned instructors and a supportive student creative community.</p>
          </article>
        </div>
      </div>
    </section>

    <section class="section" style="padding-top:8px;">
      <div class="container stats-band" aria-label="Platform statistics">
        <div class="stats-grid">
          <div>
            <p class="stat-num">425k+</p>
            <p class="stat-label">Members learning daily</p>
          </div>
          <div>
            <p class="stat-num">30k+</p>
            <p class="stat-label">Creative classes</p>
          </div>
          <div>
            <p class="stat-num">9k+</p>
            <p class="stat-label">Expert teachers</p>
          </div>
          <div>
            <p class="stat-num">4.8</p>
            <p class="stat-label">App Store rating</p>
          </div>
        </div>
      </div>
    </section>

    <section class="section" id="courses">
      <div class="container">
        <span class="eyebrow">Courses</span>
        <h2 class="heading">Discover classes by category</h2>
        <p class="sub">Switch categories to instantly explore courses tailored to your creative goals.</p>

        <div class="tabs" role="tablist" aria-label="Course categories tabs">
          <button class="tab-btn" role="tab" aria-selected="true" data-category="featured">Featured</button>
          <button class="tab-btn" role="tab" aria-selected="false" data-category="music">Music</button>
          <button class="tab-btn" role="tab" aria-selected="false" data-category="drawing">Drawing &amp; Painting</button>
          <button class="tab-btn" role="tab" aria-selected="false" data-category="marketing">Marketing</button>
          <button class="tab-btn" role="tab" aria-selected="false" data-category="animation">Animation</button>
          <button class="tab-btn" role="tab" aria-selected="false" data-category="uiux">UI/UX</button>
        </div>

        <div id="courseGrid" class="course-grid" aria-live="polite"></div>
      </div>
    </section>

    <section class="section" style="padding-top:0;">
      <div class="container">
        <span class="eyebrow">Creative Feed</span>
        <h2 class="heading">See what learners are making</h2>
        <div class="feed-grid" aria-label="Student project feed">
          <div class="feed-item" style="background:linear-gradient(135deg,#fdba74,#fb7185);"><span>Character Design</span></div>
          <div class="feed-item" style="background:linear-gradient(135deg,#93c5fd,#60a5fa);"><span>Brand Mockup</span></div>
