        { title: 'Portrait Painting with Acrylic Layers', instructor: 'Theo Grant', students: '19,445', duration: '4h 12m', category: 'Drawing & Painting', bg: 'linear-gradient(135deg,#c4b5fd,#a78bfa)' },
      ],
      marketing: [
        { title: 'Creative Brand Strategy from Zero to Launch', instructor: 'Parker Sun', students: '25,778', duration: '3h 58m', category: 'Marketing', bg: 'linear-gradient(135deg,#fdba74,#fb923c)' },
        { title: 'Reels and Shorts for Artist Growth', instructor: 'Zoe Ahmed', students: '31,004', duration: '2h 22m', category: 'Marketing', bg: 'linear-gradient(135deg,#f9a8d4,#f472b6)' },
        { title: 'Portfolio Positioning for Freelancers', instructor: 'Jules Park', students: '16,932', duration: '2h 55m', category: 'Marketing', bg: 'linear-gradient(135deg,#93c5fd,#3b82f6)' },
      ],
      animation: [
