        { title: 'Storyboarding for Short Films', instructor: 'Leo Dean', students: '13,618', duration: '3h 05m', category: 'Animation', bg: 'linear-gradient(135deg,#fca5a5,#ef4444)' },
        { title: 'Character Rigging Essentials', instructor: 'Jin Park', students: '9,302', duration: '4h 40m', category: 'Animation', bg: 'linear-gradient(135deg,#86efac,#22c55e)' },
