        { title: 'UX Research for Product Creators', instructor: 'Marlon Reed', students: '15,008', duration: '3h 29m', category: 'UI/UX', bg: 'linear-gradient(135deg,#67e8f9,#0891b2)' },
        { title: 'High-Converting Landing Pages in Figma', instructor: 'Nora Blake', students: '20,443', duration: '2h 48m', category: 'UI/UX', bg: 'linear-gradient(135deg,#fcd34d,#f59e0b)' },
      ]
    };

    const teachers = [
      { name: 'Ari Vega', role: 'Illustrator', bg: 'linear-gradient(135deg,#fb7185,#f43f5e)' },
      { name: 'Mila Rowan', role: 'Digital Designer', bg: 'linear-gradient(135deg,#60a5fa,#2563eb)' },
      { name: 'Kai Mercer', role: 'Animator, Product Designer', bg: 'linear-gradient(135deg,#34d399,#059669)' },
      { name: 'Noor Shah', role: 'Graphic Designer', bg: 'linear-gradient(135deg,#fbbf24,#f97316)' },
      { name: 'Elena Park', role: 'Watercolor Artist', bg: 'linear-gradient(135deg,#22d3ee,#0ea5e9)' },
      { name: 'Dylan Ross', role: 'Motion Graphics Artist', bg: 'linear-gradient(135deg,#a78bfa,#7c3aed)' },
    ];

    const courseGrid = document.getElementById('courseGrid');
    const tabBtns = Array.from(document.querySelectorAll('.tab-btn'));

    function renderCourses(category) {
      const items = courseData[category] || [];
      courseGrid.innerHTML = items.map(c => `
        <article class="course-card">
          <div class="thumb" data-category="${c.category}" style="background:${c.bg};"></div>
          <div class="course-body">
            <h3 class="course-title">${c.title}</h3>
            <p class="course-teacher">by ${c.instructor}</p>
            <div class="course-meta"><span>${c.students} students</span><span>${c.duration}</span></div>
          </div>
        </article>
      `).join('');
    }

    tabBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        tabBtns.forEach(b => b.setAttribute('aria-selected', 'false'));
        btn.setAttribute('aria-selected', 'true');
        renderCourses(btn.dataset.category);
      });
    });
    renderCourses('featured');

    const track = document.getElementById('teacherTrack');
    track.innerHTML = teachers.map(t => `
      <article class="teacher-card">
        <div class="teacher-img" style="background:${t.bg};"></div>
        <div class="teacher-body">
          <h3 class="teacher-name">${t.name}</h3>
          <p class="teacher-role">${t.role}</p>
        </div>
      </article>
    `).join('');

    document.getElementById('teacherPrev').addEventListener('click', () => {
      track.scrollBy({ left: -260, behavior: 'smooth' });
    });
    document.getElementById('teacherNext').addEventListener('click', () => {
      track.scrollBy({ left: 260, behavior: 'smooth' });
    });

    const faqItems = Array.from(document.querySelectorAll('.faq-item'));
    faqItems.forEach(item => {
      item.querySelector('.faq-btn').addEventListener('click', () => {
        const wasOpen = item.dataset.open === 'true';
        faqItems.forEach(i => i.dataset.open = 'false');
        item.dataset.open = wasOpen ? 'false' : 'true';
      });
    });

    const modal = document.getElementById('signupModal');
    const modalText = document.getElementById('modalText');

    function openModal(text) {
      modal.dataset.open = 'true';
      modal.setAttribute('aria-hidden', 'false');
      modalText.textContent = text;
    }

    function closeModal() {
      modal.dataset.open = 'false';
      modal.setAttribute('aria-hidden', 'true');
    }

    document.getElementById('googleSignupBtn').addEventListener('click', () => {
      openModal('Google sign-up initiated. Continue with your Google account to start your free trial.');
    });

    document.getElementById('emailSignupBtn').addEventListener('click', () => {
      openModal('Continue with email to create your CreativeHub account.');
      document.getElementById('emailInput').focus();
    });

    document.getElementById('closeModalBtn').addEventListener('click', closeModal);
    modal.addEventListener('click', (e) => {
      if (e.target === modal) closeModal();
    });
  </script>
</body>
</html>
